import 'dart:convert';

import 'package:flutter/services.dart';

import '../../../core/resources/app_assets.dart';

/// Reads the JSON seeds bundled with the app (generated by tool/build_seed.py from the xlsx).
class SeedAssetDataSource {
  SeedAssetDataSource(this._bundle);

  final AssetBundle _bundle;

  Future<Map<String, Object?>> _json(String path) async =>
      jsonDecode(await _bundle.loadString(path, cache: false)) as Map<String, Object?>;

  Future<Map<String, Object?>> questionnaire() => _json(AppAssets.questionnaireSeed);

  Future<Map<String, Object?>> cities() => _json(AppAssets.citiesSeed);

  Future<Map<String, Object?>> researchers() => _json(AppAssets.researchersSeed);
}
